script:
def walk(path):
    out = []
    for name in repo.list(path):
        full = path + "/" + name if path != "." else name
        if name.endswith("/"):
            out.extend(walk(full.rstrip("/")))
        else:
            out.append(full)
    return out

allf = walk("src")
files = {}
for f in allf:
    files[f] = repo.read(f)
result({"list": allf, "contents": files})
